//! B06950 normal-frame caller composed with concrete owned queue/quota runtimes.
//! Remaining consumer and callback bodies are mandatory explicit services.
use crate::{audio_bus_bank::Error,audio_common_queue::{Context,RetryServices},audio_due_actions,audio_callback_registry::{Registry,Reason},audio_device_factory as factory,audio_fallback_device as fallback,audio_frame_quota::Scheduler,audio_factory_fallback};
fn word(raw:&[u8],o:usize)->u32{u32::from_le_bytes(raw[o..o+4].try_into().unwrap())}
fn set(raw:&mut[u8],o:usize,v:u32){raw[o..o+4].copy_from_slice(&v.to_le_bytes());}
#[derive(Clone,Copy)]pub enum Pass{Commands,DueActions}
#[derive(Clone,Copy)]pub enum Post{A,B,C,D}
pub struct Runtime{
 pub common_reference:u32,pub common:Context,pub due:audio_due_actions::Runtime,pub registry:Registry,
 pub factory:factory::Runtime,pub fallback:fallback::Runtime,pub scheduler:Scheduler,pub outputs:factory::Outputs,
 pub processed:u32,pub command_pool:u32,pub rate:u32,pub recorder_pool:u32,pub optional:u8,pub final_reference:u32,pub advance_a:u32,pub advance_b:u32,
}
pub trait Services:factory::Virtual+fallback::Services+RetryServices+audio_due_actions::Services{
 fn lock_frame(&mut self)->Result<(),Error>;
 fn unlock_frame(&mut self)->Result<(),Error>;
 fn optional(&mut self,runtime:&mut Runtime)->Result<(),Error>;
 fn callback(&mut self,registry:&mut Registry,runtime:&mut Runtime,key:u32,reason:Reason)->Result<(),Error>;
 fn advance_a(&mut self,runtime:&mut Runtime,reference:u32,frame:u32)->Result<(),Error>;
 fn advance_b(&mut self,runtime:&mut Runtime,reference:u32,frame:u32)->Result<(),Error>;
 fn post(&mut self,runtime:&mut Runtime,phase:Post)->Result<(),Error>;
 fn finalize(&mut self,runtime:&mut Runtime,reference:u32)->Result<(),Error>;
 /// Passive audit only. Owned consumers execute independently of observation.
 fn observe_pass(&mut self,_reference:u32,_pass:Pass){}
 fn observe_node_advance(&mut self,_reference:u32,_frame:u32){}
}
impl Runtime{
 /// Configure and activate a path against this caller's live clock/pool, before
 /// frame traversal. Physical history allocation is a mandatory service.
 pub fn initialize_path(&self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,paths:&mut crate::audio_timed_node_segment::Runtime,selection:&mut crate::audio_timed_node_selection::Runtime,reference:u32,input:&mut crate::audio_path_configuration::Configuration,services:&mut impl crate::audio_path_configuration::Services)->Result<u32,Error>{
  if input.pool!=self.command_pool{return Err(Error::InvalidAllocation);}let status=crate::audio_path_configuration::configure(nodes,paths,selection,reference,input,services)?;if status!=1{return Ok(status);}crate::audio_path_activation::start(nodes,paths,bindings,selection,reference,&mut input.state,word(&self.common.raw,0x7c),services)
 }

 /// Initialize using the native resource caller's guard and loop extraction.
 pub fn initialize_resource_path(&self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,paths:&mut crate::audio_timed_node_segment::Runtime,selection:&mut crate::audio_timed_node_selection::Runtime,reference:u32,resource:&crate::audio_plugin_factory::Memory,state:&mut [u8;8],services:&mut impl crate::audio_path_configuration::Services)->Result<u32,Error>{
  let input=crate::audio_path_configuration::from_resource(resource,*state,self.command_pool)?;
  let status=crate::audio_path_configuration::configure_guarded(nodes,paths,selection,reference,&input,services)?;
  if status!=1{return Ok(status);}
  crate::audio_path_activation::start(nodes,paths,bindings,selection,reference,state,word(&self.common.raw,0x7c),services)
 }

 pub fn run(&mut self,services:&mut impl Services)->Result<(),Error>{self.run_with_advance_b(services,|runtime,reference,frame,services|services.advance_b(runtime,reference,frame))}
 pub fn run_with_nodes<S:Services+crate::audio_frame_node_update::Services>(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,services:&mut S)->Result<(),Error>{
  self.run_with_advance_b(services,|_,reference,frame,services|{if nodes.reference!=reference{return Err(Error::UnresolvedReference);}services.observe_node_advance(reference,frame);nodes.update(frame,services)})
 }
 pub fn run_with_timed_nodes<S:Services+crate::audio_timed_node_update::Services>(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,services:&mut S)->Result<(),Error>{
  self.run_with_advance_b(services,|_,reference,frame,services|{if nodes.reference!=reference{return Err(Error::UnresolvedReference);}services.observe_node_advance(reference,frame);nodes.update(frame,&mut crate::audio_timed_node_update::Backend{bindings,backend:services})})
 }
 pub fn run_with_paths<S:Services+crate::audio_timed_node_segment::Services>(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,paths:&mut crate::audio_timed_node_segment::Runtime,services:&mut S)->Result<(),Error>{
  self.run_with_advance_b(services,|_,reference,frame,services|{if nodes.reference!=reference{return Err(Error::UnresolvedReference);}services.observe_node_advance(reference,frame);let mut segments=crate::audio_timed_node_segment::Backend{paths,backend:services};nodes.update(frame,&mut crate::audio_timed_node_update::Backend{bindings,backend:&mut segments})})
 }
 pub fn run_with_native_paths<S:Services+crate::audio_timed_node_segment::Services+crate::audio_timed_node_restart::Services>(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,paths:&mut crate::audio_timed_node_segment::Runtime,services:&mut S)->Result<(),Error>{
  self.run_with_advance_b(services,|_,reference,frame,services|{if nodes.reference!=reference{return Err(Error::UnresolvedReference);}services.observe_node_advance(reference,frame);let mut restart=crate::audio_timed_node_restart::Backend{backend:services};let mut segments=crate::audio_timed_node_segment::Backend{paths,backend:&mut restart};nodes.update(frame,&mut crate::audio_timed_node_update::Backend{bindings,backend:&mut segments})})
 }
 pub fn run_with_selection<S:Services+crate::audio_timed_node_segment::Services+crate::audio_timed_node_restart::Services>(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,bindings:&mut crate::audio_timed_node_update::Runtime,paths:&mut crate::audio_timed_node_segment::Runtime,selection:&mut crate::audio_timed_node_selection::Runtime,services:&mut S)->Result<(),Error>{
  self.run_with_advance_b(services,|_,reference,frame,services|{if nodes.reference!=reference{return Err(Error::UnresolvedReference);}services.observe_node_advance(reference,frame);let mut select=crate::audio_timed_node_selection::Backend{selection,backend:services};let mut restart=crate::audio_timed_node_restart::Backend{backend:&mut select};let mut segments=crate::audio_timed_node_segment::Backend{paths,backend:&mut restart};nodes.update(frame,&mut crate::audio_timed_node_update::Backend{bindings,backend:&mut segments})})
 }
 fn run_with_advance_b<S:Services>(&mut self,services:&mut S,mut advance_b:impl FnMut(&mut Self,u32,u32,&mut S)->Result<(),Error>)->Result<(),Error>{
  services.lock_frame()?;let result=self.run_locked(services,&mut advance_b);let unlock=services.unlock_frame();result.and(unlock)
 }
 fn run_locked<S:Services>(&mut self,services:&mut S,advance_b:&mut impl FnMut(&mut Self,u32,u32,&mut S)->Result<(),Error>)->Result<(),Error>{
  let mut quota=audio_factory_fallback::quota(&mut self.factory,&mut self.fallback,&mut self.scheduler,&mut self.outputs,self.rate,self.recorder_pool,services)?;
  loop{
   services.observe_pass(self.common_reference,Pass::Commands);self.common.consume(&mut self.processed,services)?;
   services.observe_pass(self.common_reference,Pass::DueActions);self.due.drain(&mut self.common.raw,&mut self.processed,self.command_pool,services)?;
   if self.optional!=0{services.optional(self)?;}
   if quota==0{break;}
   let mut registry=std::mem::take(&mut self.registry);let dispatch=registry.dispatch(Reason::Frame,|registry,key,reason|services.callback(registry,self,key,reason));self.registry=registry;dispatch?;
   let frame=word(&self.common.raw,0x7c).wrapping_add(1);let reference=self.advance_a;services.advance_a(self,reference,frame)?;let reference=self.advance_b;advance_b(self,reference,frame,services)?;
   for phase in [Post::A,Post::B,Post::C,Post::D]{services.post(self,phase)?;}
   let counter=word(&self.common.raw,0x7c).wrapping_add(1);set(&mut self.common.raw,0x7c,counter);quota-=1;
  }
  if self.final_reference!=0{let reference=self.final_reference;services.finalize(self,reference)?;}Ok(())
 }
}
