 impl crate::audio_path_configuration::Services for Initialization{fn allocate_history(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{let reference=self.next;self.next=self.next.wrapping_add(4);self.calls.push(json!({"kind":"path_allocate","pool":pool,"bytes":bytes,"reference":reference}));Ok(Some(self.masks.remove(&reference).ok_or(Error::UnresolvedReference)?))}}
 fn binding_map(v:&Value)->BTreeMap<u32,Memory>{v.as_array().unwrap().iter().map(|e|{let reference=e["reference"].as_u64().unwrap()as u32;(reference,Memory{reference,raw:bytes(e["raw"].as_str().unwrap())})}).collect()}
 fn binding_snapshot(map:&BTreeMap<u32,Memory>)->Vec<Value>{map.values().map(|m|json!({"reference":m.reference,"raw":hex(&m.raw)})).collect()}
 impl crate::audio_timed_node_segment::Services for Backend{
  fn restart_path(&mut self,nodes:&mut crate::audio_frame_node_update::Runtime,_:&mut crate::audio_timed_node_segment::Runtime,reference:u32)->Result<u32,Error>{let index=u16::from_le_bytes(nodes.nodes[&reference].raw[20..22].try_into().unwrap());if self.node_append{nodes.nodes.get_mut(&reference).unwrap().raw[20..22].fill(0);if !self.node_appended{let count=word(&nodes.header,4)as usize;set(&mut nodes.table.raw,count*4,0x30038180);set(&mut nodes.header,4,count as u32+1);self.node_appended=true;}}let status=if self.node_append{1}else{52};self.calls.push(json!({"kind":"restart_path","reference":reference,"index_before":index,"status":status}));Ok(status)}
  fn observe_random(&mut self,value:u16){self.calls.push(json!({"kind":"rand","value":value}));}
  fn observe_node_update(&mut self,reference:u32,frame:u32){self.calls.push(json!({"kind":"node_update","reference":reference,"frame":frame}));}
  fn observe_segment_advance(&mut self,reference:u32){self.calls.push(json!({"kind":"finish_node","reference":reference}));}
 }
 impl crate::audio_timed_node_restart::Services for Backend{
  fn select_path(&mut self,_:&mut crate::audio_frame_node_update::Runtime,_:&mut crate::audio_timed_node_segment::Runtime,_:u32)->Result<bool,Error>{Err(Error::Backend("unexpected random path selection in sequential fixture"))}
  fn observe_restart(&mut self,reference:u32){self.calls.push(json!({"kind":"restart_path","reference":reference}));}
 }
